function EagleLayer({ color }: { color: string }) {
  return (
    <Svg width="100%" height="100%" viewBox="450 485.512 600 348">
      <Path d={EAGLE_PATH} fill={color} />
    </Svg>
  );
}

export function EagleLogo({ color = "#181511" }: { color?: string }) {
  return <EagleLayer color={color} />;
}

export function FlyingEagleLogo({ color = "#181511" }: { color?: string }) {
  const reduceMotion = useReducedMotion();
  const flight = useSharedValue(0);

  useEffect(() => {
    if (reduceMotion) {
      flight.value = 0.5;
      return;
    }
    flight.value = withRepeat(
      withSequence(
        withTiming(1, { duration: 920, easing: Easing.inOut(Easing.cubic) }),
        withTiming(0, { duration: 920, easing: Easing.inOut(Easing.cubic) }),
      ),
      -1,
      false,
    );
    return () => cancelAnimation(flight);
  }, [flight, reduceMotion]);

  const flightStyle = useAnimatedStyle(() => ({
    opacity: 0.96 + flight.value * 0.04,
    transform: [
      { translateY: 3 - flight.value * 6 },
      { rotateZ: `${-0.8 + flight.value * 1.6}deg` },
      { scale: 0.985 + flight.value * 0.025 },
    ],
  }));

  return (
    <Animated.View style={[styles.stage, flightStyle]}>
      <EagleLayer color={color} />
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  stage: { width: "100%", height: "100%" },
});
